export function DropZone({
  zoneLabel = "{{zoneLabel}}",
  dragOver = {{dragOver}},
  acceptance = "{{acceptance}}",
  accent = "{{accent}}",
}) {
  const overStyle = dragOver
    ? (acceptance === "reject"
        ? { borderColor: "#b3261e", background: "#b3261e14", color: "#b3261e" }
        : { borderColor: accent, background: "color-mix(in srgb, " + accent + " 16%, #FAF7F2)", color: "#241430" })
    : {};
  return (
    <div style={{ width: 280, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ border: "2px dashed #24143033", borderRadius: 12, padding: "26px 16px", textAlign: "center", color: "#241430aa", ...overStyle }}>
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M12 3v12M7 10l5 5 5-5M4 21h16" /></svg>
        <p style={{ margin: "8px 0 0", fontSize: 13 }}>{zoneLabel}</p>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430aa" }}>{dragOver ? "drop target active" : "rest state \u2014 drag a file over the dashed zone"}</p>
    </div>
  );
}
